// Config: edit these values once. Every other node reads them via $('Config').first().json
// If n8n runs in Docker and Neo4j/Ollama run on the host, use host.docker.internal.
// If n8n runs directly on Windows (npm / desktop), use localhost.
return [{
  json: {
    neo4j_url: 'http://host.docker.internal:7474',
    neo4j_db: 'neo4j',
    ollama_url: 'http://host.docker.internal:11434',
    embed_model: 'nomic-embed-text',
    // Scryfall set code(s) to ingest. One set is ~250-300 cards. Space separated for several: 'fdn dsk'
    set_codes: 'fdn',
    // Paste the current TXT link from https://magic.wizards.com/en/rules
    cr_url: 'PASTE_COMPREHENSIVE_RULES_TXT_URL_HERE',
  },
}];

const input = $('Start').first().json;
const k = Math.min(Math.max(parseInt(input.k) || 5, 1), 15);
const params = { k, embedding: $input.first().json.embeddings[0] };
const statement = "CALL () {
  CALL db.index.vector.queryNodes('rule_chunk_embedding', $k, $embedding) YIELD node, score
  RETURN node, score
  UNION ALL
  CALL db.index.vector.queryNodes('ruling_chunk_embedding', $k, $embedding) YIELD node, score
  RETURN node, score
}
RETURN node.source_type AS kind, node.text AS text, round(score, 3) AS score, node.source AS source
ORDER BY score DESC
LIMIT $k";
return [{ json: { statements: [{ statement, parameters: params }] } }];

// Turns the Neo4j HTTP response into plain objects for the agent.
const res = $input.first().json;
if (res.errors?.length) throw new Error('Neo4j error: ' + JSON.stringify(res.errors));
const r = res.results[0];
let rows = r.data.map(d => Object.fromEntries(r.columns.map((c, i) => [c, d.row[i]])));
if (rows.length && 'score' in rows[0]) rows.sort((a, b) => b.score - a.score);
return [{ json: { count: rows.length, results: rows } }];
